  --color-border-strong: #bdbdbd;
  --color-primary: #1e5386;
  --color-primary-hover: #1a4570;
  --color-primary-strong: #2a7e3b;
  --color-secondary: #2770b2;
  --color-surface: #fcfcfc;
  --color-surface-inverse: #13273e;
  --color-surface-sunken: #f3f7fc;
  --color-text-inverse: #fcfcfc;
  --color-text-link: #1e5386;
  --color-text-muted: #7c7c7c;
  --color-text-primary: #3d3d3d;
  --color-text-secondary: #525252;
  --color-text-tertiary: #656565;
  --container-gutter: 2rem;
  --font-display: "IBM Plex Sans Condensed", "IBM Plex Sans", sans-serif;
  --font-sans: "IBM Plex Sans", sans-serif;
  --font-weight-bold: 700;
  --font-weight-medium: 500;
  --font-weight-regular: 400;
  --font-weight-semibold: 600;
  --form-font-size-md: clamp(0.75rem, 0.66rem + 0.44vw, 0.9375rem);
  --form-font-size-sm: clamp(0.625rem, 0.56rem + 0.32vw, 0.75rem);
  --form-height-md: 40px;
  --form-height-sm: 32px;
  --form-padding-x-md: 0.75rem;
  --form-padding-x-sm: 0.625rem;
  --form-radius-md: 0.5rem;
  --form-radius-sm: 0.25rem;
  --icon-link-font-size-md: 1rem;
  --icon-link-font-size-sm: 0.875rem;
  --icon-link-gap: 0.375rem;
  --icon-size-md: 20px;
  --icon-size-medium: 20px;
  --icon-size-sm: 16px;
  --icon-size-small: 16px;
  --icon-size-xs: 14px;
  --link-column-heading-font-size: clamp(0.75rem, 0.66rem + 0.44vw, 0.9375rem);
  --link-column-item-font-size: clamp(0.6875rem, 0.61rem + 0.38vw, 0.875rem);
  --link-column-rule-color: color-mix(in srgb, currentColor 40%, transparent);
  --radius-100: 0.25rem;
  --side-dialog-width: 400px;
  --side-dialog-width-sm: 320px;
  --spacing-100: 0.25rem;
  --spacing-150: 0.375rem;
  --spacing-200: 0.5rem;
  --spacing-300: 0.75rem;
  --spacing-400: 1rem;
  --spacing-500: 1.5rem;
  --spacing-600: 2rem;
  --spacing-650: 2.5rem;
  --spacing-800: 4rem;
  --transition-fast: 0.15s ease;
  --type-size-150: clamp(0.6875rem, 0.61rem + 0.38vw, 0.875rem);
  --type-size-200: clamp(0.75rem, 0.66rem + 0.44vw, 0.9375rem);
}

*,
*:before,
*:after {
  box-sizing: border-box;
}
body {
  margin: 0;
  font-family: var(--font-sans, system-ui, sans-serif);
  color: var(--color-text-primary, #171717);
  background: var(--color-surface, #fff);
  -webkit-font-smoothing: antialiased;
}
a {
  color: var(--color-text-link, #1e5386);
  text-decoration: none;
}
.cbf-app-bar--admin {
  --app-bar-gap: var(--spacing-650);
}
.esa-app-bar {
  --_bar-gap: var(--app-bar-gap, var(--spacing-600, 32px));
  --_bar-pad-x: var(--app-bar-pad-x, var(--spacing-600, 32px));
  --_bar-pad-y: var(--app-bar-pad-y, var(--spacing-400, 16px));
  display: block;
  width: 100%;
  background: var(--app-bar-bg, var(--color-surface, #fff));
  color: var(--app-bar-text, var(--color-text-primary, #171717));
}
.esa-app-bar--brand-strong {
  background: var(--app-bar-brand-strong-bg, var(--color-surface-inverse, #171717));
  color: var(--app-bar-brand-strong-text, var(--color-text-inverse, #fff));
}
.esa-app-bar__row {
  display: flex;
  align-items: center;
  gap: var(--_bar-gap);
  padding: var(--_bar-pad-y) var(--_bar-pad-x);
}
.esa-app-bar__start,
.esa-app-bar__main,
.esa-app-bar__end {
  display: inline-flex;
  align-items: center;
  gap: var(--_bar-gap);
}
.esa-app-bar__start {
  flex: none;
}
button {
  font-family: inherit;
  cursor: pointer;
  background: none;
  border: 0;
}
.esa-icon-link {
  --_il-font: var(--icon-link-font-size-md, 1rem);
  display: inline-flex;
  align-items: center;
  gap: var(--icon-link-gap, var(--spacing-150, 6px));
  padding: 0;
  margin: 0;
  border: 0;
  background: none;
  color: inherit;
  font-family: var(--font-sans, system-ui, sans-serif);
  font-size: var(--_il-font);
  font-weight: var(--font-weight-medium, 500);
  line-height: 1;
  text-decoration: none;
  cursor: pointer;
  white-space: nowrap;
}
.esa-icon-link--sm {
  --_il-font: var(--icon-link-font-size-sm, 0.875rem);
}
.esa-icon-link--medium {
  font-weight: var(--font-weight-medium, 500);
}
.esa-icon-link__label {
  display: inline-block;
}
.esa-app-bar__main {
  flex: 1 1 auto;
}
.esa-app-bar__end {
  flex: none;
  margin-left: auto;
}
summary.esa-icon-link {
  list-style: none;
}
.cbf-app-bar--header {
  --app-bar-gap: var(--spacing-800);
}
.esa-app-bar--brand {
  background: var(--app-bar-brand-bg, var(--color-primary, #43608a));
  color: var(--app-bar-brand-text, var(--color-text-inverse, #fff));
}
img {
  display: block;
  max-width: 100%;
}
.stack {
  --gap: var(--spacing-400, 1rem);
  display: flex;
  flex-direction: column;
  gap: var(--gap);
}
[data-gap="lg"] {
  --gap: var(--spacing-500, 1.5rem);
}
:where(h1, h2, h3, h4, h5, h6, p, figure, blockquote, dl, dd, ul, ol, pre) {
  margin: 0;
}
.esa-container {
  width: 100%;
  max-width: var(--_container-max, 1556px);
  margin-inline: auto;
  padding-inline: var(--container-gutter, var(--spacing-600, 2rem));
}
.esa-breadcrumbs {
  --_crumb-font-size: var(--type-size-200, 0.875rem);
  --_crumb-link-color: var(--breadcrumbs-link-color, #43608a);
  --_crumb-link-hover: var(--breadcrumbs-link-hover, #39506f);
  --_crumb-current-color: var(--color-text-primary, #171717);
  --_crumb-separator-color: var(--breadcrumbs-separator-color, #737373);
  --_crumb-gap: var(--spacing-200, 8px);
  display: block;
}
.esa-breadcrumbs__list {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: var(--_crumb-gap);
  list-style: none;
  margin: 0;
  padding: 0;
  font-size: var(--_crumb-font-size);
}
.esa-breadcrumbs__item {
  display: flex;
  align-items: center;
  gap: var(--_crumb-gap);
}
.esa-breadcrumbs__link {
  display: inline-flex;
  align-items: center;
  gap: var(--spacing-100, 4px);
  color: var(--_crumb-link-color);
  text-decoration: none;
}
.esa-breadcrumbs__icon {
  display: inline-flex;
  align-items: center;
}
.esa-breadcrumbs__separator {
  flex-shrink: 0;
  color: var(--_crumb-separator-color);
}
.esa-breadcrumbs__current {
  display: inline-flex;
  align-items: center;
  gap: var(--spacing-100, 4px);
  color: var(--_crumb-current-color);
  font-weight: var(--font-weight-medium, 500);
}
html:has(.msow-page) {
  height: 100%;
}
html:has(.msow-page) body {
  height: 100%;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}
.skip-link {
  position: absolute;
  top: -40px;
  left: 0;
  background: var(--color-secondary);
  color: var(--color-text-inverse, #fff);
  padding: 8px 12px;
  z-index: 9999;
  font-size: 13px;
  font-weight: var(--font-weight-bold);
  border-radius: 0 0 4px;
  transition: top 0.1s;
}
.msow-page {
  flex: 1;
  display: flex;
  flex-direction: column;
  padding-block: var(--spacing-600);
  overflow: hidden;
  min-height: 0;
}
.msow-page .esa-container {
  flex: 1;
  display: flex;
  flex-direction: column;
  min-height: 0;
}
.msow-card {
  flex: 1;
  display: flex;
  flex-direction: column;
  min-height: 0;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-100);
  overflow: hidden;
  background: var(--color-surface);
  box-shadow: 0 1px 3px color-mix(in srgb, var(--color-surface-inverse) 8%, transparent);
}
.msow-crumb-strip {
  background: var(--color-gold-50);
  border-bottom: 1px solid var(--color-border);
  padding: var(--spacing-400) var(--spacing-600);
  flex-shrink: 0;
}
.msow-crumb-strip .esa-breadcrumbs {
  --breadcrumbs-link-color: var(--color-text-secondary);
  --breadcrumbs-link-hover: var(--color-primary);
}
.msow-toolbar {
  background: var(--color-surface);
  border-bottom: 1px solid var(--color-border);
  padding: var(--spacing-300) var(--spacing-600);
  flex-shrink: 0;
  display: flex;
  align-items: center;
  gap: var(--spacing-600);
}
.msow-toolbar-identity {
  display: flex;
  flex-direction: column;
  gap: 2px;
  flex-shrink: 0;
}
.msow-tool-title {
  margin: 0;
  font-size: 16px;
  font-weight: var(--font-weight-bold);
  font-family: var(--font-display, var(--font-sans));
  color: var(--color-surface-inverse);
  white-space: nowrap;
  line-height: 1.2;
}
.msow-contract-meta {
  display: flex;
  align-items: center;
  gap: var(--spacing-100);
  font-size: 11px;
  color: var(--color-text-muted);
}
.msow-meta-sep {
  color: var(--color-border-strong);
}
.msow-toolbar-actions {
  display: flex;
  align-items: center;
  gap: var(--spacing-200);
  flex-shrink: 0;
  margin-left: auto;
}
.msow-root {
  font-size: 13px;
}
.msow-root {
  flex: 1;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  min-height: 0;
}
.msow-root * {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}
#msow-layout {
  display: flex;
  flex: 1;
  overflow: hidden;
  min-height: 0;
}
#wizard-panel {
  width: 260px;
  flex-shrink: 0;
  background: var(--color-surface-sunken);
  border-right: 1px solid var(--color-border);
  display: flex;
  flex-direction: column;
  overflow: hidden;
  min-height: 0;
}
#sidebar {
  width: 300px;
  flex-shrink: 0;
  background: var(--color-surface);
  border-right: 1px solid var(--color-border);
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
#wizard-body-panel {
  display: flex;
  flex-direction: column;
  height: 100%;
  overflow: hidden;
  background: var(--color-surface-sunken);
}
#expert-panel {
  display: none;
  flex-direction: column;
  height: 100%;
  overflow: hidden;
}
#mapwrap {
  flex: 1;
  position: relative;
  overflow: hidden;
  user-select: none;
  -webkit-user-select: none;
}
#map {
  width: 100%;
  height: 100%;
  user-select: none;
  -webkit-user-select: none;
}
#map-hint {
  position: absolute;
  top: 10px;
  left: 50%;
  transform: translate(-50%);
  background: color-mix(in srgb, var(--color-primary) 92%, transparent);
  color: var(--color-text-inverse, #fff);
  padding: 5px 14px;
  border-radius: 16px;
  font-size: 11px;
  pointer-events: none;
  z-index: 999;
  display: none;
  white-space: nowrap;
}
#draw-done-btn {
  display: none;
  position: absolute;
  top: 52px;
  left: 50%;
  transform: translate(-50%);
  z-index: 1000;
  background: var(--color-primary);
  color: var(--color-text-inverse, #fff);
  border: none;
  padding: 6px 16px;
  border-radius: 16px;
  font-size: 12px;
  font-weight: var(--font-weight-bold);
  font-family: var(--font-sans, system-ui, sans-serif);
  cursor: pointer;
  box-shadow: 0 2px 8px #0000004d;
  transition: background 0.15s ease;
}
#edit-done-bar {
  display: none;
  position: absolute;
  top: 52px;
  left: 50%;
  transform: translate(-50%);
  z-index: 1000;
  align-items: center;
  gap: var(--spacing-200);
  white-space: nowrap;
}
#map-legend {
  position: absolute;
  bottom: 10px;
  left: 10px;
  background: #fffffff7;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-100);
  padding: 8px 10px;
  font-size: 11px;
  z-index: 999;
  box-shadow: 0 2px 8px #0000001f;
  min-width: 160px;
}
.leg-title {
  font-size: 10px;
  font-weight: var(--font-weight-bold);
  color: var(--color-surface-inverse);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  margin-bottom: 5px;
  display: flex;
  justify-content: space-between;
}
.leg-toggle {
  cursor: pointer;
  color: var(--color-text-muted);
  font-weight: var(--font-weight-regular);
  text-transform: none;
  letter-spacing: 0;
  font-size: 11px;
}
.leg-body.collapsed {
  display: none;
}
#we-modal {
  display: none;
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: #00000080;
  z-index: 3000;
  align-items: center;
  justify-content: center;
}
#sowmodal {
  display: none;
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: #00000080;
  z-index: 2000;
  align-items: center;
  justify-content: center;
}
.msow-welcome-card {
  background: var(--color-surface);
  width: 440px;
  border-radius: var(--radius-100);
  overflow: hidden;
  box-shadow: 0 8px 32px #00000040;
}
.msow-welcome-head {
  background: var(--color-primary);
  padding: var(--spacing-500) var(--spacing-600);
  border-bottom: 3px solid var(--color-primary-hover);
}
.msow-welcome-title {
  color: var(--color-text-inverse, #fff);
  font-size: 15px;
  font-weight: var(--font-weight-bold);
  margin: 0;
}
.msow-welcome-body {
  padding: var(--spacing-500) var(--spacing-600) var(--spacing-500);
}
.msow-welcome-heading {
  font-size: 14px;
  font-weight: var(--font-weight-bold);
  color: var(--color-surface-inverse);
  margin-bottom: var(--spacing-300);
}
.msow-welcome-desc {
  font-size: 12px;
  color: var(--color-text-tertiary);
  line-height: 1.65;
}
.msow-welcome-actions {
  padding: 0 20px 20px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.msow-welcome-btn,
.msow-welcome-btn .esa-button {
  display: block;
}
.leaflet-top.leaflet-left {
  display: flex;
  flex-direction: row;
  align-items: flex-start;
  gap: 6px;
}
.leaflet-control-zoom {
  border: none !important;
  box-shadow: 0 2px 8px #0000004d !important;
  flex-shrink: 0;
}
.leaflet-top.leaflet-left .leaflet-control {
  margin-bottom: 0 !important;
}
.layer-control-container {
  background: transparent;
}
.zoom-we-btn {
  display: block;
  background: var(--color-primary);
  color: var(--color-text-inverse, #fff);
  border: none;
  padding: 5px 10px;
  border-radius: 4px;
  cursor: pointer;
  font-size: 12px;
  font-weight: var(--font-weight-semibold);
  box-shadow: 0 1px 4px #0006;
  white-space: nowrap;
}
.layer-control-btn {
  background: var(--color-primary);
  color: var(--color-text-inverse, #fff);
  border: none;
  padding: 5px 10px;
  border-radius: 4px;
  cursor: pointer;
  font-size: 12px;
  font-weight: var(--font-weight-semibold);
  box-shadow: 0 1px 4px #0006;
  white-space: nowrap;
}
.layer-control-panel {
  background: var(--color-primary);
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: 4px;
  padding: 10px 12px;
  margin-top: 4px;
  min-width: 170px;
  box-shadow: 0 2px 8px #0006;
}
:host {
  --_width: var(--side-dialog-width, 400px);
}
:host([size="sm"]) {
  --_width: var(--side-dialog-width-sm, 320px);
}
.cbf-app-bar--admin {
  --app-bar-pad-y: var(--spacing-300);
}
.cbf-app-bar--admin .esa-app-bar__row {
  display: grid;
  grid-template-columns: 1fr minmax(0, 380px) 1fr;
}
.cbf-app-bar--admin .esa-app-bar__start {
  justify-self: start;
}
.cbf-nav-collapsible {
  display: contents;
}
.cbf-app-bar--admin .esa-app-bar__main {
  justify-content: center;
}
.cbf-omni-trigger {
  display: flex;
  align-items: center;
  gap: var(--spacing-200);
  width: 380px;
  max-width: 100%;
  padding: 5px var(--spacing-200) 5px var(--spacing-300);
  background: #ffffff1a;
  border: 1px solid rgba(255, 255, 255, 0.22);
  border-radius: 999px;
  color: #ffffffbf;
  transition:
    background 0.12s,
    border-color 0.12s;
}
.cbf-app-bar--admin .cbf-omni-trigger {
  min-width: 0;
}
.cbf-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: none;
  color: inherit;
}
.cbf-omni-trigger__ph {
  flex: 1;
  min-width: 0;
  text-align: left;
  font-size: 13px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.cbf-omni-trigger__kbd {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 18px;
  height: 18px;
  padding: 0 5px;
  font-family: var(--font-sans);
  font-size: 13px;
  font-weight: var(--font-weight-medium);
  color: #ffffffd9;
  background: #ffffff1f;
  border: 1px solid rgba(255, 255, 255, 0.25);
  border-radius: 4px;
}
.cbf-app-bar--admin .esa-app-bar__end {
  justify-self: end;
}
.esa-nav-dropdown {
  position: relative;
}
.esa-nav-dropdown .esa-icon-link > .esa-icon:last-child {
  transition: transform 0.15s ease;
}
.cbf-nav-burger {
  display: none;
}
.cbf-logo {
  display: inline-flex;
  align-items: center;
  gap: var(--spacing-300, 12px);
  flex: none;
  color: inherit;
  text-decoration: none;
}
.cbf-logo__mark {
  width: 48px;
  height: 48px;
  flex: none;
}
.cbf-logo__type {
  height: 40px;
  width: auto;
}
.cbf-nav-actions {
  display: inline-flex;
  align-items: center;
  gap: var(--spacing-600);
}
.cbf-nav-link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: inherit;
  background: none;
  border: 0;
  font-size: 16px;
  font-weight: var(--font-weight-medium);
  white-space: nowrap;
}
.cbf-nav-link .cbf-icon {
  display: inline-flex;
  align-items: center;
}
.cbf-nav-link--user {
  position: relative;
  padding-left: var(--spacing-500);
}
.cbf-nav-link--user:before {
  content: "";
  position: absolute;
  left: 0;
  top: 50%;
  transform: translateY(-50%);
  width: 1px;
  height: 1.1em;
  background: #ffffff40;
}
.cbf-omni {
  position: fixed;
  inset: 0;
  z-index: 80;
}
.cbf-omni[hidden] {
  display: none;
}
.esa-link-column {
  color: inherit;
}
.esa-link-column__head {
  display: block;
  margin: 0 0 var(--spacing-100, 4px);
  font-size: var(--link-column-heading-font-size, var(--type-size-200, 1rem));
  font-weight: var(--font-weight-medium, 500);
  color: inherit;
  text-decoration: none;
}
.esa-link-column__rule {
  height: 1px;
  border: 0;
  margin: 0 0 var(--spacing-200, 8px);
  background: var(--link-column-rule-color, color-mix(in srgb, currentColor 40%, transparent));
}
.esa-link-column__list {
  list-style: none;
  margin: 0;
  padding: 0;
}
.esa-link-column__list li {
  font-size: var(--link-column-item-font-size, var(--type-size-150, 0.875rem));
  line-height: 22px;
  margin-bottom: var(--spacing-100, 4px);
}
.esa-link-column__list a {
  color: inherit;
  text-decoration: none;
}
.esa-button {
  --_btn-height: var(--form-height-md, 40px);
  --_btn-padding-x: var(--form-padding-x-md, 16px);
  --_btn-font-size: var(--form-font-size-md, 14px);
  --_btn-radius: var(--form-radius-md, 6px);
  --_accent: var(--color-primary, #46a758);
  --_accent-hover: var(--color-primary-hover, #3e9b4f);
  --_on: var(--color-text-inverse, #ffffff);
  --_accent-text: var(--_accent);
  --_btn-tint-hover: color-mix(in srgb, var(--_accent) 8%, transparent);
  --_btn-tint-active: color-mix(in srgb, var(--_accent) 14%, transparent);
  display: inline-block;
}
.esa-button--sm {
  --_btn-height: var(--form-height-sm, 32px);
  --_btn-padding-x: var(--form-padding-x-sm, 12px);
  --_btn-font-size: var(--form-font-size-sm, 12px);
  --_btn-radius: var(--form-radius-sm, 4px);
}
.esa-button__native {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--spacing-200, 8px);
  width: 100%;
  height: var(--_btn-height);
  padding-inline: var(--_btn-padding-x);
  border: 1px solid transparent;
  border-radius: var(--_btn-radius);
  font-size: var(--_btn-font-size);
  font-family: var(--font-sans, system-ui, sans-serif);
  font-weight: var(--font-weight-medium, 500);
  line-height: 1;
  text-decoration: none;
  cursor: pointer;
  transition:
    background var(--transition-fast, 0.15s ease),
    border-color var(--transition-fast, 0.15s ease);
  -webkit-appearance: none;
  appearance: none;
}
.esa-button--sm .esa-button__native {
  height: auto;
  padding-block: var(--spacing-150, 6px);
}
.esa-button--appearance-outline .esa-button__native,
.esa-button--appearance-dashed .esa-button__native {
  background: transparent;
  color: var(--_accent-text);
  border-color: var(--_accent);
}
.esa-button--color-ghost .esa-button__native {
  background: transparent;
  color: var(--color-text-primary, #171717);
  border-color: transparent;
}
.esa-button--color-ghost.esa-button--appearance-outline .esa-button__native,
.esa-button--color-ghost.esa-button--appearance-dashed .esa-button__native {
  border-color: var(--color-border, #e5e5e5);
}
.esa-button__label {
  white-space: nowrap;
}
.esa-button--color-primary {
  --_accent-text: var(--color-primary-strong);
}
.esa-button--appearance-fill .esa-button__native {
  background: var(--_accent);
  color: var(--_on);
  border-color: transparent;
}
.esa-icon {
  --_icon-size: var(--icon-size-md, var(--icon-size-medium, 20px));
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: var(--_icon-size);
  height: var(--_icon-size);
  line-height: 1;
  color: inherit;
}
.esa-icon--xs {
  --_icon-size: var(--icon-size-xs, 14px);
}
.esa-icon svg {
  display: block;
  width: var(--_icon-size);
  height: var(--_icon-size);
}
.esa-icon--sm {
  --_icon-size: var(--icon-size-sm, var(--icon-size-small, 16px));
}
.esa-icon--md {
  --_icon-size: var(--icon-size-md, var(--icon-size-medium, 20px));
}
